INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mickeys-adventure-in-numberland--1', 18102, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6oqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce02h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey''s Adventure in Numberland', '"Oh no", cried Donald the Sheriff. "Pete''s done it again!" "He''s stolen our numbers-from 1 up through 10!" "Search the whole city-every street every house." "Look high and low-and call Mickey Mouse!" "You can count on me," declared Mickey Mouse. "Don''t worry!" "I''ll find all the numbers. I''ll foil Pete''s plot!" "I''m set for adventure. I''m hot on the trail." "With my friends to help guide me, there''s no way I can fail!" Immensely entertaining, Mickey''s Adventure in Numberland helps improve early number identification and counting skills as it invites children to join Mickey on his quest to locate and return Numberland''s stolen numbers. The game features 5 imaginative worlds of fun and fantasy-each with two levels and a seemingly endless supply of animated surprises. Mickey''s Adventures in Numberland is an educational game released for the NES in March of 1994.' FROM games WHERE igdb_id = 18102 ON CONFLICT (game_id, language_code) DO NOTHING;
