INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mario-andretti-racing', 20593, '1994-12-31', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ntt.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Andretti Racing', 'Italian-born Mario Andretti is one of the most successful racing drivers in the US scene, and five of his relatives have also raced professionally. This game allows you to sample Indy cars, stock cars and sprint cars, all of which have been graced by Andrettis. The physics are customized to each of these, so expect sprint cars to slide around on the dirt tracks, and the slipstream effect is detectable. There are 27 computer-controlled cars with individual profiles, and 8 cars to choose from in each race, with varying engine, grip, brakes and pit crew standards. You can view the action either from behind the car, or from the nose. In longer races you must monitor the pit strategy, with the options of a splash ''n'' dash stop if your tires are still fine.' FROM games WHERE igdb_id = 20593 ON CONFLICT (game_id, language_code) DO NOTHING;
