INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar: Eternal Blue', 'Come back to the enchanting world of Lunar! Join Hiro and Ruby 1,000 years after the first adventure, as they work to unlock the secrets of the Blue Spire and the strange young girl they found within it! But be careful! Forces are at work trying to revive the evil Zophar and immerse Lunar in darkness forever! Journey to distant lands in search of the Goddess Althena, who may be the only one powerful enough to stop Zophar. Along the way, you''ll meet exciting new characters, fight fully animated monsters, traverse snow-covered peaks, and crawl through slimy dungeons as you work towards the terrifying climax!' FROM games WHERE igdb_id = 5401 ON CONFLICT (game_id, language_code) DO NOTHING;
