INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Oasis', 'Prince Ali has excavated a gold armlet which belonged to a powerful sorcerer. As soon as Ali tried on the armlet, a strange fire with a face appeared and spoke to him. “The power of the gold armlet is now your’s to wield. Find the four spirits this gold armlet governs and stop the evil ambitions of the one with the silver armlet.”' FROM games WHERE igdb_id = 15299 ON CONFLICT (game_id, language_code) DO NOTHING;
