INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Jam Tournament Edition', 'NBA Jam Tournament Edition brings you more senses-shattering slam dunking excitement than ever! More than twice as many NBA superstars, more than double the secret characters, Hot Spots, Super Jam Power-Ups, battery back-up and - OH MY - nine all-new rim-rattling slam dunks plus all the original jams! NBA JAM Tournament Edition... it''s on FIRE!' FROM games WHERE igdb_id = 19712 ON CONFLICT (game_id, language_code) DO NOTHING;
