INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ranma ½: Chougi Ranbu-hen', 'Ranma gets a letter explaining that they just received the recipe to the most valuable of all treasures, the Maneki Neko, which has the ability to grant any wish. Ranma must then set out to find the 12 ingredients of the Maneki Neko, located all over the world, before one of their rivals does the same. The game was scheduled to be released in North America under the title of Ranma ½ II: Anything-Goes Martial Arts, but went unreleased in the West.' FROM games WHERE igdb_id = 42739 ON CONFLICT (game_id, language_code) DO NOTHING;
