INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('armored-warriors', 13688, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22y9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5y0a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Armored Warriors', 'In the year 2281, the war spanning half a century over territory between the United World Forces and the Raian Kingdom had at last come to an end. But this peace was not to last. A year after a truce was signed between the two forces, former Raian army captain Azrael, who has converted himself into a cyborg in an attempt to become "the perfect warrior", has marshalled several thousand other cyborgs and declared war against the Raian Kingdom. Robbing mobile weapons from the army, this group of rogues has invaded the Raian capital of Merkid and has begun to abduct the civilians. The United World Government, receiving an emergency message from the planet Raia, has but one choice: to organize and dispatch an army formed around its elite corps, a squadron of warriors called "Bloody Armor", to eradicate the enemy forces and rescue the civilians. And so, in October 2282, the United World Forces begin to launch its attack upon the planet Raia. The most intense battle in human history is about to begin...' FROM games WHERE igdb_id = 13688 ON CONFLICT (game_id, language_code) DO NOTHING;
