INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-s-quest-vii-the-princeless-bride--1', 7514, '1994-11-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28rx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvc3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest VII: The Princeless Bride', 'King''s Quest VII: The Princeless Bride is an adventure game in the King''s Quest series. The game features two playable characters: Queen Valanice and her daughter, Princess Rosella, who become separated in a magical realm called Eldritch. Players alternate between the two characters as they navigate through six chapters, each set in a distinct fantasy world. The story revolves around Rosella''s unexpected journey to Eldritch and Valanice''s quest to find her daughter, with both facing various challenges and encountering colorful characters along the way. King''s Quest VII departs from the series'' traditional art style, adopting a more cartoon-like aesthetic inspired by Disney animated films. The game incorporates point-and-click gameplay, puzzle-solving, and character interactions typical of the adventure genre, while expanding on the King''s Quest universe with new locations and a focus on female protagonists.' FROM games WHERE igdb_id = 7514 ON CONFLICT (game_id, language_code) DO NOTHING;
