INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-cup-golf-professional-edition', 4340, '1994-12-31', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coapeb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Cup Golf: Professional Edition', 'Take on the best with WORLD CUP GOLF: Professional Edition. Get onto the green in the Practice mode, and work on any hole that gives you problems. In Normal mode, challenge the course alone or play against someone with 15 different game types such as skins and match play. Tournament mode provides you with the ability to create your own event. No matter how you play the course, you''ll have full control over your player''s stance as well as the weather and the ground conditions. While you play, your auditory sense is treated to CD quality music and digitized speech. See how long you would last as an expert in WORLD CUP GOLF: Professional Edition.' FROM games WHERE igdb_id = 4340 ON CONFLICT (game_id, language_code) DO NOTHING;
