INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mighty Morphin Power Rangers', 'The Sega Genesis/Mega Drive version of Mighty Morphin Power Rangers is a one-on-one competitive fighting game, featuring two different game modes: a Scenario Mode where the player competes against a series of CPU-controlled opponents, and a Battle Mode for two players. In the Scenario Mode, the matches consist of two segments: the player will fight against a regular-sized monster as one of the Rangers, and after the defeating the monster they will battle a giant version of it. Initially, only the five original Rangers and the Megazord are available.' FROM games WHERE igdb_id = 75974 ON CONFLICT (game_id, language_code) DO NOTHING;
