INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('twinsens-little-big-adventure-classic', 8515, '1994-10-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kf5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ibx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twinsen''s Little Big Adventure Classic', 'Chilling dreams of destruction and doom fill your mind. You feel compelled to warn the world, but in so doing are imprisoned by the tyrannous Dr. Funfrock. Imprisoned because of a dream? You know in your soul that you must escape somehow and discover the meaning behind this mystery. As Twinsen, prophet and savior, you embark on a surreal and suspense-filled journey. You cross continents in your quest to save the world and stop your evil nemesis. At any moment, your enemies may overtake you, stopping you in your pursuit of the Legend. Relentless you must be, for only those who remain pure can overcome the peril that awaits. Twinsen''s Little Big Adventure Classic is a real gem in the genre. There is nothing else like it. The game is filled with surreal action and adventure that will make you laugh many times because you can hardly believe the kind of crazy things they''ve thought up. So if you are in a mood for a crazy adventure with great story, clever puzzles with more than one solution, and open world then you can’t go wrong with this masterpiece of a game.' FROM games WHERE igdb_id = 8515 ON CONFLICT (game_id, language_code) DO NOTHING;
