INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Children of the Atom', 'X-Men: Children of the Atom is an arcade game featuring characters licensed from Marvel Comics. Timed with the popularity of the mid-1990s X-Men animated series, the game incorporates voice actors from the show reprising their respective roles. The gameplay involves one-on-one fighting matches, where players face off against different characters in the game. The ultimate challenge comes in the form of battles against Juggernaut and Magneto.' FROM games WHERE igdb_id = 39295 ON CONFLICT (game_id, language_code) DO NOTHING;
