INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeon-master-ii-the-legend-of-skullkeep', 2503, '1994-03-25', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yn4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/irayeidnihxkybcazm1p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Master II: The Legend of Skullkeep', 'Dungeon Master established several new standards for role playing and computer games in general. Dungeon Master was a realtime game instead of the traditional turn-based approach that was prevalent until then. Instead of using text-based commands to interact with the environment, players directly manipulated objects and the environment by clicking the mouse in the enlarged first-person view. Abstract Dungeons and Dragons style experience points and levels were eschewed in favor of a system where the characters'' skills were improved directly via using them. It also introduced some novel control methods including the spell casting system, which involved learning sequences of runes which represented the form and function of a spell''s effect. For example, a fireball spell was created by mixing the fire symbol with the wing symbol. This kind of attention to detail and focus on the user interface was typical of the game and helped create an often captivating sense of craft and ingenuity. Other factors in immersiveness were the then-revolutionary use of sound effects to indicate when a creature was nearby, and (primitive) dynamic lighting.' FROM games WHERE igdb_id = 2503 ON CONFLICT (game_id, language_code) DO NOTHING;
