INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimTower', 'Welcome to the building simulation game SimTower, which offers the chance to build and manage all the complex, interconnected operations of a modern skycraper. You build your empire from nothing and become the engineer and general manager of your structure. You can provide offices, coffee shops or apartments to anyone who is willing to pay.' FROM games WHERE igdb_id = 7519 ON CONFLICT (game_id, language_code) DO NOTHING;
