INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flintstones: The Treasure of Sierra Madrock', 'Rock this town! Join the gang from Bedrock on their latest fun filled adventure. It''s your chance to play with the stars! -12 megs of excellent action! -One or two players! -Five worlds with multiple stages provide hours of entertainment! -Races, roulette, and many more mini-games! -Awesome intermission screens bring Bedrock to life!' FROM games WHERE igdb_id = 8450 ON CONFLICT (game_id, language_code) DO NOTHING;
