INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('contra-hard-corps', 20192, '1994-08-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n11.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8w1x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contra: Hard Corps', 'Kickin'' cyborg butt... That''s what it''s all about, dude. Jack into this game of genetic engineering gone bad. Real bad. It''s five years after the mother of all wars ended - and things still aren''t right. Your job is to fix it. The ever-popular Contra series makes its Sega Genesis debut with a pulse-pounding new storyline. At 16 megs, HARD CORPS pushes the technology to bring you over ten gut-wrenching levels with huge boss characters, great graphics and dynamic sound. Find high powered weapons such as the homing gun, crush gun, needle laser or mine setter. Do you think you can handle it? Trust me, you can''t. You still here? Okay, then get ready for the fight of your life. Pick one of the four heroes and begin your search across many dark levels of doom. The ending changes, depending on the paths you choose - but every pass crosses boss characters that will blow you away. Literally!' FROM games WHERE igdb_id = 20192 ON CONFLICT (game_id, language_code) DO NOTHING;
