INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('raptor-call-of-the-shadows', 9082, '1994-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jju.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars4a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raptor: Call of the Shadows', 'It''s the BEST IBM shooter yet! A fast paced slugfest, with a pulse-pounding sound track, and jaw-dropping VGA animation & cinematics. In the future as a mercenary flying the super-tech Raptor, you''ll be sent on interplanetary missions to knock off top competitors of MegaCorp. Battle against hordes of relentless enemies. Spend the bounty you receive from their demise to expand your devastating arsenal, which can be upgraded with 14 hard core weapons! "Raptor has some of the hottest graphics ever seen in a shareware game, and blows away most commercial games, too! The graphics will amaze you and the sound will astound you. It''s a super star!" -- Interactive Entertainment Raptor sets the new standard for PC shooters. This game will do for shooters what Wolfenstein did for 3D games. Incredibly smooth VGA graphics and animation are only half the story. The heart-pounding music in Raptor will leave you breathless, especially if you have a high-end sound card like the Roland or Wave Blaster. (Raptor supports the Midi music format, which provides very high quality music for PC games.) All other major sound cards are also supported! The addictive quality and replay value of this game is unreal. Discover secrets, find the bonuses, and battle the boss ships that appear at the end of EVERY WAVE! With each ship and ground target you destroy, you''ll earn more cash to increase your ship''s technology for the next wave. You''ll be driven to kill and destroy--but then, it''s in your blood.' FROM games WHERE igdb_id = 9082 ON CONFLICT (game_id, language_code) DO NOTHING;
