INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster World IV', 'Experience the fourth chapter in the classic Monster World series! One day, a young, green-haired girl names Asha, hears spirits calling out for help. Upon hearing the spirits, she leaves her village and sets forth on a grand adventure into Monster World. One her journey, she comes across a small blue monster named Pepe and a magical Genie. Together they must fight through Monster Land to defeat evil and save the troubled Elemental Spirits.' FROM games WHERE igdb_id = 18282 ON CONFLICT (game_id, language_code) DO NOTHING;
