INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('puyo-puyo-tsuu--1', 45976, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cd5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9h7v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo Tsuu', 'The object of this head-to-head puzzle game is to clear your grid of falling patterns, called puyos, by forming chains of four or more same-colored puyos in a straight line or one of several geometric patterns. What makes this a challenging two-player contest is the fact that when you clear a chain of puyos from your grid, it drops a random piece of filler onto your opponent’s grid. The more puyos you clear, the more you fill your opponent’s grid, and if you can clutter up his grid enough to fill it to the top, you’ve won the game. An intriguing backstory makes this an amusing experience for one or two players.' FROM games WHERE igdb_id = 45976 ON CONFLICT (game_id, language_code) DO NOTHING;
