INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('descent', 1872, '1994-12-31', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xmo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfks.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Descent', 'Welcome to Descent - 30 levels of the most mind-bending, stomach-churning action game ever. Featuring true 3-Dimensional worlds with light source shading, texture mapping, 3-D morphing, directional sound effects and sizzling music, this is technology taken to the limit.You begin deep below the surface of Lunar Base I where an unknown alien race has taken over the chasm of the Post-Terran Mining Corporation. Lunge straight down mine shafts, twist around never-ending tunnels and fight your way past robotic menaces in an environment that''s truly 360° 3-D... move up, move down, shoot everything everywhere. Hang onto your senses (and your lunch) as you drop straight down mine shafts on a ride that''ll leave you spinning.And what''s the good of losing your mind if you can''t share the experience with your friends? Descent invites you and your buddies to dive into the action together with head-to-head combat and cooperative two-player modem and eight-player network support.' FROM games WHERE igdb_id = 1872 ON CONFLICT (game_id, language_code) DO NOTHING;
