INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima VIII: Pagan', 'The Ultima VIII Pagan starts exactly where Ultima VII ended. Avatar is cast to the world of Pagan by the Guardian. In the meantime, the Guardian is taking control over Britannia and Avatar has to find the way to leave Pagan and save Britannia from the Guardian. The world of Pagan is ruled by four titans that prevent any interworld travel. To open a portal to Britannia, Avatar has to destroy all four titans ad claim their power.' FROM games WHERE igdb_id = 2520 ON CONFLICT (game_id, language_code) DO NOTHING;
