INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('x-men-mutant-apocalypse', 42576, '1994-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dgk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scb0bp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Mutant Apocalypse', 'Because of a rise of anti-mutant activity in Genosha, Professor Xavier uses Cerebro to scan the island nation and discovers Apocalypse''s presence there. Genosha''s government is apparently using Apocalypse to bring their mutant population under control. However, Xavier suspects Apocalypse to follow his own plans and sends five X-Men, Cyclops, Wolverine, Psylocke, Beast and Gambit, to investigate. X-Men: Mutant Apocalypse combines the gameplay of a side-scrolling brawler like Final Fight with elements of a platformer, that is, players have to fight various enemies and survive the occasional jumping-puzzle. Most levels also feature mid- and end-bosses in form of robots, monsters or known Super-Villains. Each character has unique abilities and special moves: Cyclops uses his Optic Blast to attack enemies from a distance, Wolverine can climb walls, Psylocke is very agile and the best jumper of the team, Beast can cling to the ceiling while Gambit throws explosive cards at his enemies. Special moves are quite similar to those found in Street Fighter II (Wolverine has a Dragon-Punch-style attack and Gambit''s Double Kick is virtually identical to M. Bison''s Scissors Kick), and require similar button combinations. While most stages are unique for each character, some can be played with any of the X-Men. Progress is saved via password.' FROM games WHERE igdb_id = 42576 ON CONFLICT (game_id, language_code) DO NOTHING;
