INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubsy II', 'Defeat droves of dive-bombing penguins! Squash squadrons of flying pigs! Trash tons of turbo-powered sheep! It''s all waiting for you in this wacky, whirlwind adventure through the Amazatorium. FIVE wild worlds. FOUR claw-biting levels of difficulty. THREE mind-boggling mini-games. TWO hopelessly lost relatives. and ONE wise-cracking bobcat named Bubsy.' FROM games WHERE igdb_id = 7803 ON CONFLICT (game_id, language_code) DO NOTHING;
