INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wing-commander-iii-heart-of-the-tiger', 2588, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2khu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21ll.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing Commander III: Heart of the Tiger', 'Wing Commander is a space combat simulator intercut with live action cutscenes. Gameplay involves completing missions and destroying enemy craft, Wing commander III dispensed with the issuing of medals after such missions and relied more on cutscenes to drive the story along making much more use of CD technology. As the man giving the orders, Blair often gets to choose what ship he will fly, what missiles it will carry, and what wingman (wingmen) he will take with him. As in Wing Commander, some wingmen can be killed permanently in combat. Blair''s own call sign remained customizable' FROM games WHERE igdb_id = 2588 ON CONFLICT (game_id, language_code) DO NOTHING;
