INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tex-murphy-under-a-killing-moon', 955, '1994-10-15', 69, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zoe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar528n.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tex Murphy: Under a Killing Moon', 'Enter the virtual world of Under A Killing Moon, where it is December 2042, and you, as Tex Murphy, must stop the forces of evil before they destroy mankind and rob you of your next unemployment check. This thrilling and hilarious adventure is unlike anything you''ve seen before. The graphics quality, the fascinating, believable characters, and complete freedom of movement will make you feel like you''ve actually walked through the screen and become the main character in a rich, intriguing mystery movie. Starring Brian Keith, Margot Kidder, and Russell Means. Features the voice of James Earl Jones.' FROM games WHERE igdb_id = 955 ON CONFLICT (game_id, language_code) DO NOTHING;
