INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Carpet', 'Magic Carpet is a video game released by Bullfrog Productions in 1994. Its graphics and gameplay were considered innovative and technically impressive at the time. A revised edition, Magic Carpet Plus, included the Hidden Worlds expansion pack which added 25 levels and a winter-themed tileset. The title also had a sequel released in 1995, Magic Carpet 2. Magic Carpet was considered by critics to be a revolutionary game for its time.' FROM games WHERE igdb_id = 4415 ON CONFLICT (game_id, language_code) DO NOTHING;
