INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blackthorne', 'In Blackthorne, players take on the role of Kyle Blackthorne, a lethal commando equipped with brute strength, animal cunning, and a mysterious past that he has just begun to remember. Thrown onto the futuristic planet of Tuul, Blackthorne must contend with a world overrun by mutant monsters and goblin hordes in a valiant attempt to liberate the Androthi people.' FROM games WHERE igdb_id = 452 ON CONFLICT (game_id, language_code) DO NOTHING;
