INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-tetris-3', 42531, '1994-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3a6q.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Tetris 3', 'Super Tetris 3 is yet another version of the famous soviet puzzle game. However, despite what the title may suggest, contained within are actually four different versions of Tetris: Tetris Classic, Familiss, Sparkliss, and Magicaliss. Tetris Classic, of course, is the basic version of the game, which comes with an endless mode and a 25-line "standard" mode. Familiss, as the name might suggest, is a family mode for up to four players simultaneously. Sparkliss, meanwhile, is very similar to Bombliss from Super Tetris 2, only with a medieval fantasy theme and different explosion patterns. Sparkliss includes both a stage mode and a puzzle mode. The most unique mode is Magicaliss, which has never shown up on any other version of Tetris. In Magicaliss, pieces come in three basic colors, and by rotating the piece, the player can choose between them. Creating a line entirely out of one color will clear all blocks on the screen of that color. There are also grey pieces, which can only be cleared by creating a line made entirely from one color, which will cause all grey blocks on screen to become that color. There are also rare rainbow pieces which will act as any color. Besides these additions, the game itself is basic Tetris. Tetris Classic, Sparkliss, and Magicaliss can also be played in a two-player battle mode, besides the four-player Familiss mode.' FROM games WHERE igdb_id = 42531 ON CONFLICT (game_id, language_code) DO NOTHING;
