INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lode Runner: The Legend Returns', 'Lode Runner: The Legend Returns is a 1994 remake to the classic Lode Runner video game. The game takes place in a single frame with many different elements such as ground, ladders, treasure, items, and villains. The goal is to collect all the treasure, avoid touching any of the monks, and reach the exit. A level editor is included with the game, allowing several levels to constitute a single group of levels, as well as the ability to switch between different tile sets. The editor can choose to set the level in night or day, as well as change the background music regardless of the tile set.' FROM games WHERE igdb_id = 46964 ON CONFLICT (game_id, language_code) DO NOTHING;
