INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tiny-toon-adventures-wacky-sports-challenge', 8051, '1994-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mfh.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Toon Adventures: Wacky Sports Challenge', 'Humor! Wackiness! Sports! ls that what you''re looking for? if so. this game''s got it! Plus cool graphics. STARRING YOUR FAVORITE TINY TOON ADVENTURES CHARACTERS FROM THE ANIMATED TV SERIES!! You can play as Buster Bunny. Babs Bunny (no relation). Plucky Duck or Dizzy Devil! You''ll also run into your other favorite cast characters. HIDDEN BONUSES!!! TWELVE DIFFERENT EVENTS!!! MULTIPLE SKILL LEVELS WITH DIFFERENT HAZARDS!!! Face it. if you want a laugh riot. sports action. and tons of replay value. then this is the game you''re looking for! Just check out those screen shots. BUY THE GAME. PLAY THE GAME. BE THE GAME. Besides. where else are you going to find Bungee Jumping, Chicken Race. Ice Cream Toss, Weight Lifting and eight other games in one convenient package?' FROM games WHERE igdb_id = 8051 ON CONFLICT (game_id, language_code) DO NOTHING;
