INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Shodown II', 'One of SNK''s legendary fighting game series has made a return! In Samurai Shodown II, you can take on one of the roles of 15 warriors as you fight your way through the land to defeat the evil Mizuki! Slash, kick, and slice your opponents in half...do whatever it takes...live by the sword, and die by its blade.' FROM games WHERE igdb_id = 19986 ON CONFLICT (game_id, language_code) DO NOTHING;
