INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battletoads--1', 14591, '1994-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wbu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar44nl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battletoads', 'Up to three players, as the Battletoads, brawl aliens and mutant rodents through six levels to save the universe from the Dark Queen. The game also includes vertical and bonus levels. Each Toad has its own signature attack, and as customary for the series, players can knock enemies towards the screen, breaking the fourth wall. Rare took greater liberties with violence and gore in Battletoads Arcade since the product was not destined for home consoles. It was Rare''s first game to use the 3D graphics technology that was implemented in Donkey Kong Country and Killer Instinct. Although the game playtested well and appeared financially viable, the publisher hesitated to release the game. A port for the Super Nintendo was in production but canceled. The game received its console debut when it was emulated in the 2015 Rare Replay, a compilation of games from Rare''s history for the Xbox One.' FROM games WHERE igdb_id = 14591 ON CONFLICT (game_id, language_code) DO NOTHING;
