INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-aladdin--1', 106270, '1994-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaf31.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar45zw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Aladdin', 'This version of Disney''s Aladdin is a completely different game than either the SNES or Genesis versions, and was only released for SEGA''s 8-bit systems, Master System & Game Gear. It has a classic-era Prince of Persia kind of gameplay. Like the other versions, it is a side-scrolling action game. The player controls Aladdin, making his way through a variety of locations, including the streets of Agrabah, the Cave of Wonders, the Sultan''s palace and more. Gameplay takes several different forms: some levels are chases, where Aladdin runs automatically, but must be made to jump over chasms or rolling rocks and barrels, evade falling objects and avoid getting caught by a guard. Other levels are platforming affairs: Aladdin must run, jump and climb, find keys or switches to open doors while searching for the exit. Rocks can be collected and be thrown to dispatch enemies or hit buttons otherwise out of reach. Finally, there are also several magic carpet rides in the game, in which the level scrolls automatically and the player must make sure to avoid any obstacles in the way.' FROM games WHERE igdb_id = 106270 ON CONFLICT (game_id, language_code) DO NOTHING;
