INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey Mania: The Timeless Adventures of Mickey Mouse', 'Mickey Mouse gets a chance to go down memory lane and walk through the timeless adventures he has lived. Mickey Mania is a platformer where all the levels are based on Mickey''s most famous cartoons. The levels range about 75 years, starting off with "Steamboat Willie" and going all the way to "The Prince and the Pauper". The gameplay consists mostly of jumping and marble throwing at enemies, with an occasional puzzle element.' FROM games WHERE igdb_id = 5404 ON CONFLICT (game_id, language_code) DO NOTHING;
