INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EarthBound', 'A turn-based JRPG and sequel to then-Japan-only Earthbound Beginnings (1989) in which Ness, a young boy living in a land based on the USA, leaves home to go on an adventure through strange locations, get to know quirky characters and defeat an unknowable alien threat called Giygas while facing up to the realities of growing up and becoming familiar with the real world.' FROM games WHERE igdb_id = 2899 ON CONFLICT (game_id, language_code) DO NOTHING;
