INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mickey-no-tokyo-disneyland-daibouken', 42543, '1994-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vxf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7htg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey no Tokyo Disneyland Daibouken', 'Mickey has taken a trip to Tokyo Disneyland. But when he arrives, he finds out from Minnie that his friends have been kidnapped and the park has been hijacked by none other than Pete. Armed with nothing but a combo water/helium backpack and some balloons, Mickey must trek through the different sections of the park to rescue his friends, held captive in some of the park''s most iconic attractions, and stop Pete.' FROM games WHERE igdb_id = 42543 ON CONFLICT (game_id, language_code) DO NOTHING;
