INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breath of Fire II', 'The incredible sequel to the best-selling RPG hit Breath of Fire is here! You are the last member of the Dragon clan, fighting to rid the world of a growing evil. A cast of unusual and exciting companions joins you in your adventures across a wondrous land full of magic and mystery. You''ll find strange mystic items, memorable monsters and exotic locations in your quest to conquer evil. There''s strategy and spellcasting galore in the hours of compelling action and adventure that awaits you. Breath of Fire II is the ultimate in RPG excitement!' FROM games WHERE igdb_id = 6337 ON CONFLICT (game_id, language_code) DO NOTHING;
