INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sega-rally-championship', 1571, '1994-10-11', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ael.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kcoqmhikn2e5oopfnind.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Rally Championship', 'Sega Rally Championship is a 1994 arcade racing game developed by AM5 on the Sega Model 2 board. The unique selling point of Sega Rally was the ability to drive on different surfaces (including asphalt, gravel and mud), with different friction properties, with the car''s handling changing accordingly. As the first racing game to incorporate this feature, Sega Rally is considered to be one of the milestones in the evolution of the racing game genre. The music for the arcade game was composed by Takenobu Mitsuyoshi, while the Sega Saturn port''s soundtrack was done by Naofumi Hataya and the Guitar were played by Joe Satriani.' FROM games WHERE igdb_id = 1571 ON CONFLICT (game_id, language_code) DO NOTHING;
