INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wario Land: Super Mario Land 3', 'Hey! Things are really cookin'' on Kitchen Island! Wario''s got a scheme to steal the pirates'' treasure so he can have his very own castle! You help Wario get the treasure by smashing into the the magic pots! Each pot changes him into Dragon Wario, Bull Wario, or Jet Wario! With each change comes new powers! Dozens of enemies try to stop Wario, but you have the power to beat them! Be the bad guy! Explore the many exciting levels of Kitchen Island! Battery-backed memory saves your progress for many hours of fun!' FROM games WHERE igdb_id = 1072 ON CONFLICT (game_id, language_code) DO NOTHING;
