INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Death and Return of Superman', 'Brace yourself for a hard-hitting fight to the finish that lets you relive the classic DC comic book series! As Superman, fight for your life against mighty Doomsday, the vile distributor of death and destruction! Then, control the destiny of the four Supermen - each claiming to be the one, true Superman! Explode through 10 levels of super-powered battles and fly at furious speeds - until only the real Superman is left standing!' FROM games WHERE igdb_id = 453 ON CONFLICT (game_id, language_code) DO NOTHING;
