INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panic!', 'A virus has infected the world''s computer network, which effects all electronical devices on the earth. However, a special program called "Panic!" is designed to counter the effects of the virus and restore the network back to working order. You play Slap the Boy and his sidekick, Stick the Dog(they''re not actions, it''s their names) who set out to restore the network back to working order.' FROM games WHERE igdb_id = 5409 ON CONFLICT (game_id, language_code) DO NOTHING;
