INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clockwork Knight', 'Clockwork Knight is a 2.5D side-scrolling platformer where you play as the toy soldier Sir Tongara de Pepperouchau III. The game offers a combination of pre-rendered 3D graphics and 3D environment. The game has four rooms Pepper must traverse; Betsy''s room, Kevin''s room, Kitchen and Attic, each containing two levels and a boss fight at the end, with a total of five bosses and eight levels.' FROM games WHERE igdb_id = 19756 ON CONFLICT (game_id, language_code) DO NOTHING;
