INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YuYu Hakusho: Sunset Fighters', 'YuYu Hakusho: Makyou Toitsusen is a 1994 fighting game for the Sega Mega Drive by Treasure made with the Yu Yu Hakusho license — the second such game, after Nextech''s adventure game Yu Yu Hakusho Gaiden. Interestingly, TecToy published the game in Brazil as YuYu Hakusho: Sunset Fighters, however the game has not been released elsewhere. M.I.J.E.T. fan-translated the game to English in 2007. The game is a 4-player fighting game. A and B attack and C blocks, with various combos along the way. Up jumps.' FROM games WHERE igdb_id = 45607 ON CONFLICT (game_id, language_code) DO NOTHING;
