INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic the Hedgehog 3', 'The game is a sequel to the Sonic the Hedgehog 2 for the same system and follows on directly from the end of the game, in which Sonic defeated his enemy, Dr. Robotnik; crash-landing on a floating island, Sonic encounters new character Knuckles the Echidna, and must once more retrieve the Chaos Emeralds while also working to stop Dr. Robotnik from relaunching his ship, the Death Egg.' FROM games WHERE igdb_id = 6797 ON CONFLICT (game_id, language_code) DO NOTHING;
