INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rash', 'Road Rash is the third entry in the vehicular combat/racing series of the same name. It was first released on 3DO Interactive Multiplayer in 1994, received a demake of sorts on the Sega CD in 1995, and then finally arrived to Sony PlayStation, Sega Saturn and Microsoft Windows in 1996. Not to be confused with the original 1991 title on Sega Genesis/Mega Drive.' FROM games WHERE igdb_id = 141271 ON CONFLICT (game_id, language_code) DO NOTHING;
