INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inherit the Earth: Quest for the Orb', 'Join Rif the Fox and his companions Okk and Eeah on the adventure of your life! Inherit the Earth will transport you to a world of beauty and intrigue... Earth! The Orb of Storms has been stolen and Rif is accused. You have only days to help Rif get to the bottom of the mystery of the missing Orb. Your journey takes you to the Wild Lands, through hostile territories and ultimately to the ancient ruins of the legendary Humans.' FROM games WHERE igdb_id = 16726 ON CONFLICT (game_id, language_code) DO NOTHING;
