INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTV''s Beavis and Butt-Head', 'Based on the successful cartoon ''Beavis and Butt-head'', the game is very faithful to the series. It game stars at the home of Beavis and Butt-head - and from there you can choose to go to different locations like: Turbo mall 2000, the street, burger world, hospital, GWAR concert and more... your main goal is to find money to the GWAR concert.' FROM games WHERE igdb_id = 7777 ON CONFLICT (game_id, language_code) DO NOTHING;
