INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jazz Jackrabbit', 'Devan Shell, the leader of the turtle terrorists, has kidnapped the beloved rabbit princess, Eva Earlong, and has inhabited the galaxy with his looting goons! Is all hope lost for the galactic rabbits? The fate of planet Carrotus is in the hands of one lone rabbit! It''s up to you to rescue Eva Earlong and prevent Devan Shell from financing his maniacal plot of turtle domination by swiping the goods out from under his slimy beak.' FROM games WHERE igdb_id = 3167 ON CONFLICT (game_id, language_code) DO NOTHING;
