INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic & Knuckles', 'Sonic and Knuckles join forces to defeat rotten Dr. Robotnik''s Death Egg invasion! Play Sonic & Knuckles by itself or Lock-on with other Sonic games. This game''s revolutionary Lock-on technology adds all new features to your other Sonic games for ultimate replays! Play as Sonic and let loose on Robotnik with amazing new powers. Play as Knuckles and tackle Robotnik and Metal Sonic with bare-fisted attacks, high-speed glides and wall-climbing power! Lock-on with Sonic 3 and transform Floating Island into a huge 34 meg Sonic-epic loaded with new secrets! Play as Sonic, Knuckles, and even Tails - with Game Save! Lock-on with Sonic 2 and play as Knuckles with all his signature moves!' FROM games WHERE igdb_id = 9475 ON CONFLICT (game_id, language_code) DO NOTHING;
