INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jeopardy! Sports Edition', 'This version of Jeopardy! focuses more on sports related themes with 700 different categories and 3,500 questions to answer related to sports such as baseball, football, hockey, etc., along with many other sub-categories such as players, sports equipment and the like. The rules are still the same as the others, there are three rounds where the player buzzes in to answer and spells out the answers using the D-pad. It features digitized photography of sports-themed clad contestants such as baseball, football, volleyball and the like along with authentic digitized studio surroundings and the likeness and voice of long time Jeopardy! host, Alex Trebek.' FROM games WHERE igdb_id = 48977 ON CONFLICT (game_id, language_code) DO NOTHING;
