INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ravenloft-strahd-s-possession', 2508, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3hpr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arv64.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ravenloft: Strahd''s Possession', 'Lord Dhelt of Elturel was attacked in his own castle. The mysterious assassin stole the Hole Symbol of Helm, a precious amulet with magical powers. Lord Dhelt asks you to bring the amulet back. But when you kill the assassin and retrieve the amulet, you are suddenly teleported into an unknown area. The way back is blocked by poisonous mist, and there is nothing you can do but explore the hostile surroundings and to solve the mystery of the amulet. Ravenloft: Strahd''s Possession is a party-based RPG that utilizes AD&D rules. In the beginning you have a party of two people, using either pre-determined characters, or creating your own ones, picking from traditional AD&D races (human, elf, dwarf, etc.) and classes (fighter, cleric, etc.). Some characters will join your party during the course of the game, allowing maximum of four characters. Combat is done in real time. The 3D environment allows you to move smoothly through the game world, either with arrow keys, or by simply moving the mouse.' FROM games WHERE igdb_id = 2508 ON CONFLICT (game_id, language_code) DO NOTHING;
