INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamweb', 'Dreamweb is an MS-DOS and Amiga point-and-click cyberpunk top-down adventure game released in 1994, developed by Creative Reality and published by Empire Interactive Entertainment. The game features mature themes and a dark plot filled with violence and brief full frontal nudity, a rarity for games at the time. Dreamweb was re-released as freeware in October 2012.' FROM games WHERE igdb_id = 2489 ON CONFLICT (game_id, language_code) DO NOTHING;
