INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Horde', 'The Horde is a hybrid action-strategy video game that was originally released for 3DO and was ported to the Sega Saturn and DOS. It also featured full-motion video sequences featuring a number of actors including Kirk Cameron as Chauncey and Michael Gregory as Kronus Maelor. Video sequences were reduced to slide shows (with full sound) in some versions. The game was bundled with the RealMagic MPEG playback card as a demonstration of the card''s abilities to play back full-motion MPEG video via the card''s hardware decoder, at the time software MPEG decoding was not viable due to the lack of processing power in contemporary processors. The music was composed by Burke Trieschmann and won Computer Gaming World''s Premiere Award for Best Musical Score in 1994.' FROM games WHERE igdb_id = 4263 ON CONFLICT (game_id, language_code) DO NOTHING;
