INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Punch-Out!!', 'Slug your way through the grueling and sweat-pounding matches of the Minor, Major and World Circuits. Dodge bone-bruising punches and dance to the top of the supreme Special Circuit. Face off against old favorites including Bear Hugger, Piston Hurricane, Bald Bull, Mr. Sandman and Super Macho Man plus a cast of new and weird challengers. With a right hook! Body blow! And precise quick jabs! The referee announces "Knock Out!" Your opponent lies face down as you win the title of Nintendo Video Boxing Association Champion!' FROM games WHERE igdb_id = 9151 ON CONFLICT (game_id, language_code) DO NOTHING;
