INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('live-a-live', 15835, '1994-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ywe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vgh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Live A Live', 'Live A Live''s story is split across seven seemingly unrelated chapters that can be played in any order, based on popular genres such as Western, science fiction, and mecha. Each chapter has its own plot, setting, and characters. Although the basic gameplay is the same throughout the game, each chapter adds a new factor to the basic formula, such as the stealth elements in the ninja chapter. After the first seven chapters are completed, two final chapters take place to establish the connection between the seven previous and resolve the story.' FROM games WHERE igdb_id = 15835 ON CONFLICT (game_id, language_code) DO NOTHING;
