INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic the Hedgehog: Triple Trouble', 'Sonic and Tails are back with three times the fun and three times the trouble! Dr. Robotnik is building the ultimate super-weapon with the help of Knuckles, but you can stop him by getting the Chaos Emeralds first. Rip across snow and water on Sonic''s new jet skateboard or zip underwater in Tails'' "Sea Fox". But look out - Nack the Weasel is after the Emeralds, too!' FROM games WHERE igdb_id = 19556 ON CONFLICT (game_id, language_code) DO NOTHING;
