INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Star Wars: Return of the Jedi', 'All the Adventure and Excitement of the 16-bit Game -- are you ready to challenge the dark side? Choose your Rebel warrior: Luke Skywalker, Leia Organa, Han Solo, Chewbacca or Wicket the Ewok. Relive the action of the movie as you rescue Han from Jabba the Hutt, destroy the power generator on the forest moon of Endor, challenge Darth Vader and the evil Emperor and lead the Rebel assault fleet in the final battle to destroy the new Death Star! The Force will be with you as you struggle to defeat the Empire once and for all!' FROM games WHERE igdb_id = 48939 ON CONFLICT (game_id, language_code) DO NOTHING;
