INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-adventures-of-batman-robin', 5346, '1994-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co69sz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gpif5coud6czhp6ohblr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Batman & Robin', 'Now there is The Adventures of Batman and Robin. "What''s the difference?" you ask. Precisely,. Batman battles through the eight toughest levels of villainy to hit your TV screen. You''ll be dazzled by the animation-style graphics. You''ll be awed by great sound and a stirring musical score. You''ll swear you were watching the hit animated seriesexcept for one tiny detail. YOU CONTROL THE ACTION! Using a combination of brains and brawn, you decide the fate of Gotham City as you strategically lead Batman on his mission to eradicate violence and mayhem. Operating out of the top secret Batcave, you''ll use smoke bombs, Batarangs, x-ray goggles and all the weapons your utility belt can hold as you swing across rooftops and dash through dark alleys, tracking down the elusive Catwoman. You''ll try to put a stop to Two-Face as you race through the streets in the Batmobile. You''ll enlist the aid of Robin to put The Penguin out of business. You can''t relax though, because Scarecrow, The Joker, Poison Ivy, Clayface and their motley crews will crush you and take control of Gotham City!' FROM games WHERE igdb_id = 5346 ON CONFLICT (game_id, language_code) DO NOTHING;
