INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('master-of-magic', 6466, '1994-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co255e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/t8x6ar79eu1lfswmhrpo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Master of Magic', 'You came to the world of Arcanus as a fledgling wizard. Sparsely equipped with but a spell or two, you begin as the ruler of a tiny hamlet and its people. With these raw materials, you must build a thriving city, explore the two worlds of Arcanus and Myrror, expand your empire and learn new spells. In time, you will meet other wizards, each rising from equally humble beginnings, each having the same goal as you, namely conquering the worlds. How well you allocate resources, make use of your races’ potentials, seize opportunities and negotiate with other wizards determines your eventual success. In the end, though, there can be only one Master of Magic!' FROM games WHERE igdb_id = 6466 ON CONFLICT (game_id, language_code) DO NOTHING;
