INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe & Mac 2: Lost in the Tropics', 'Improving on the original''s platformer/brawler co-op gameplay, this game adds adventure and role-playing game elements that create a more involving experience compared to the first game. You can now collect coins in the levels to purchase items from Tiki Village, such as meat to recover your health, or even remodel your hut back at your home village. The game also uses a password system to track your progress. The game also shifts to an overhead map so you can wander to whichever level you wish, and return to completed levels to earn more money or power-ups.' FROM games WHERE igdb_id = 42604 ON CONFLICT (game_id, language_code) DO NOTHING;
