INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Chase III: Showdown In Orbit', 'Space Chase is a shareware side scrolling platform game in three parts, each with smoothly scrolling 16 color graphics. Part One was released as shareware with the full game being available for purchase. Later episode three was released individually as Space Chase 3. The game''s emphasis is on a combination of action and adventure. The levels are maze-like and the player will need to locate objects such as keys, switches, and moving platforms to get through.' FROM games WHERE igdb_id = 72229 ON CONFLICT (game_id, language_code) DO NOTHING;
