INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero the Kamikaze Squirrel', 'A spinoff of the Aero the Acrobat games, Zero the Kamikaze Squirrel is an over-the-top platformer that plays much like Sonic the Hedgehog. In the Aero the Acrobat games, Zero is one of the villains. However, this time around Zero is fighting to save his homeland from an evil lumberjack.' FROM games WHERE igdb_id = 38405 ON CONFLICT (game_id, language_code) DO NOTHING;
