INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Igor: Objective Uikokahonia', 'Igor, a college student, wants to date the most beautiful girl of his school. Instead he discovers a criminal plot he has to investigate. The game offers classic 2D point-and-click adventure gameplay. There are actions buttons near the bottom of the screen, as well as an inventory.' FROM games WHERE igdb_id = 7652 ON CONFLICT (game_id, language_code) DO NOTHING;
