INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bram-stokers-dracula', 14339, '1994-12-31', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6zc7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lae5wk10guzpefotnn7u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bram Stoker''s Dracula', 'Bram Stoker''s Dracula is game loosely based on the 1992 film of the same name. It was released simultaneously for multiple consoles and while the plot remains largely the same, there are differing styles of gameplay and graphics across platforms. The Amiga version is a side-scrolling action game. It uses digitized graphics for characters that were recycled from the Sega CD game however the setup is quite different. In this version there are nine stages in the game to play through. Each stage has a primary task that involves finding and destroying all the coffins that have Transylvanian earth inside, in order to advance in the game, but the last coffin to be destroyed is guarded by one of Dracula''s stronger minions, in each stage.' FROM games WHERE igdb_id = 14339 ON CONFLICT (game_id, language_code) DO NOTHING;
