INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pulseman', 'Pulseman is a platform game only released on cartridge for a Japanese audience, but was available to North American consumers via the Sega Channel. The game was not sold in Europe. It was developed by Game Freak, the development team that would later go on to produce the Pokémon series of games for Nintendo. Many of Pulseman''s staff, including director Ken Sugimori and composer Junichi Masuda worked on both games.' FROM games WHERE igdb_id = 45760 ON CONFLICT (game_id, language_code) DO NOTHING;
