INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Buyuu Retsuden', 'Dragon Ball Z: Buyu Retsuden is a fighting video game based upon Akira Toriyama''s Dragon Ball franchise. It is the only game in the series released for the Mega Drive, following the Frieza and Cell sagas. Its gameplay has been described as a combination of the original Super Butōden and Super Butōden 2, consisting of one-on-one fights using a three-button configuration, featuring special moves and two playable modes.' FROM games WHERE igdb_id = 2548 ON CONFLICT (game_id, language_code) DO NOTHING;
