INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z 2: Super Battle', 'Dragon Ball Z 2: Super Battle is a video game for arcades based on the anime Dragon Ball Z. It was designed and manufactured exclusive in Japan by Banpresto in 1995. The game is a direct sequel the previous arcade Dragon Ball Z game, produced two years earlier.' FROM games WHERE igdb_id = 2562 ON CONFLICT (game_id, language_code) DO NOTHING;
