INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rats!', 'Rats! is a frantic game of rodent extermination in a race against time before the rats have a chance to mate and overrun the maze. To stop the vermin you use bombs, radioactive waste, gas, poison, plague rats, blocks and gender changing chemicals. Each weapon has its own characteristics so they need to be placed strategically or the rat population will keep increasing. And as the rat population increases your pulse rate will too!' FROM games WHERE igdb_id = 61662 ON CONFLICT (game_id, language_code) DO NOTHING;
