INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Tick', 'Get ready to put your blue skin-tight tights on. Ninjas need beating-up, bosses need clobbering! You run around the levels avoiding sharp flying objects and fighting any enemies that get in your way, including the numerous bosses. If your in a tight spot you can call Arthur to help defeat any enemies that are on-screen.' FROM games WHERE igdb_id = 46594 ON CONFLICT (game_id, language_code) DO NOTHING;
