INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xatax', 'Xatax is a side-scrolling shooter in which the player must defend the remains of the Alliance''s guilds against the titular aliens. This is accomplished in a traditional shoot-em-up fashion, fighting waves of alien ships and stationary turrets. The player-controlled ship can become stronger by collecting power capsules dropped by defeated enemies. The game features three different worlds, of which the shareware version only contains the first.' FROM games WHERE igdb_id = 94932 ON CONFLICT (game_id, language_code) DO NOTHING;
