INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Lies', 'True Lies is a top-view action shooting game based on the 1994 film of the same title that was developed by Beam Software and published by Acclaim and LJN. Four different versions of the game were released for the Super Nintendo Entertainment System, Sega Mega Drive/Genesis, Sega Game Gear, and the Game Boy. The home versions and portable versions were drastically different from each other, but featured similar play mechanics.' FROM games WHERE igdb_id = 9702 ON CONFLICT (game_id, language_code) DO NOTHING;
