INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Itchy & Scratchy in Miniature Golf Madness', 'Itchy & Scratchy in Miniature Golf Madness is a miniature golf game released on the Game Boy in 1994, featuring the cat and mouse pair Itchy & Scratchy from the television series The Simpsons. Developed by Beam Software, it was the first game to feature these characters. In the game, the player controls Scratchy as he plays through a miniature golf course of nine holes while at the same time avoiding Itchy''s attacks. It received generally mixed to positive reviews from critics.' FROM games WHERE igdb_id = 2836 ON CONFLICT (game_id, language_code) DO NOTHING;
