INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smurfs', 'Smurf to the rescue! Gargamel has already captured 4 Smurfs, Jocky Smurf, Greedy Smurf, Brainy Smurf and Smurfette. To free them you will have to smurf the Angry Smurfs and BUZZ flies before smurfing the mountain by sled, then smurfing the maze mine galleries, smurfing on the back of a stork to smurf Azrael and finally smurf Gargamel from his mansion! Good Smurf!' FROM games WHERE igdb_id = 8083 ON CONFLICT (game_id, language_code) DO NOTHING;
