INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reunion', 'Around a distant Sun lies the planet of your ancestors - Earth. Forced to flee from anarchy and chaos you are finally ready to return for the REUNION. As President all decisions are yours to make. You must not fail...' FROM games WHERE igdb_id = 12471 ON CONFLICT (game_id, language_code) DO NOTHING;
