INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Strike: The Sequel to Jungle Strike', 'Urban Strike is a helicopter based shoot ''em up, mixing action and strategy, retaining its predecessor''s core mechanics, and expanding on the model with additional vehicles and settings. This time, the campaign takes the player all over the North American continent, beginning in Hawaii and moving through locations in Mexico, San Francisco, New York, and Las Vegas.' FROM games WHERE igdb_id = 4492 ON CONFLICT (game_id, language_code) DO NOTHING;
