INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'YuYu Hakusho: Tokubetsu-hen', 'Yu Yu Hakusho: Tokubetsu Hen ("Yu Yu Hakusho: Special Edition") is a fighter game. Rather than controlling the character directly with the D-pad and buttons, the players charge attacks and unleash them at the right amount of power. Combat is depicted as a series of dramatic cutaways as each fighter launches their attacks and the other tries to defend or evade them.' FROM games WHERE igdb_id = 42532 ON CONFLICT (game_id, language_code) DO NOTHING;
