INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Michael Jordan: Chaos in the Windy City', 'This is no pick up game... It''s a twisted adventure created by vengeful mad scientist Dr. Max Cranium! He has kidnapped an entire basketball team. And they''re under lock and key in every corner of his dark and dangerous lair beneath the street of Chicago. Control Michael Jordan''s every move as he takes on the evil Dr. Max Cranium to rescue his teammates.' FROM games WHERE igdb_id = 42490 ON CONFLICT (game_id, language_code) DO NOTHING;
