INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('generations-lost', 19784, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5lfq.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generations Lost', 'Generations Lost is a platform action game in which the player takes the role of Monobe, an adventurer on the search for the past of his people. Thanks to his magic armour Monobe is able to execute many different moves. Besides running and jumping, Monobe can roll on the ground, deliver blows with hands and feet, and shoot energy balls. With the help of an energy rope Monobe can swing from platform to platform. Most of the time, Monobe has to solve several puzzles, find secret switches and survive deadly traps. The game is split into six areas which can be accessed via the "Magic Box" teleporter.' FROM games WHERE igdb_id = 19784 ON CONFLICT (game_id, language_code) DO NOTHING;
