INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jammit', 39018, '1994-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p5a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5rzn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jammit', 'Whiners, better give this game a miss, ''cause Jammit''s the closest thing you''ll ever find to real street hoops. Don''t even think of looking for an official--in this game, it''s jam-or-be-jammed--and great D leaves the opposition gasping. In Intensive Care. Step onto one of the five stylin'' courts, and the air show begins. Revers jams. Fade-away jumpers. And way more attitude--and altitude--than you''ll ever find in the so-called pros. Get past our three asphalt warriors, and we''ll send you to meet the Judge, and you''d better bring your license to drive. Put some money down, talk a little trash, then walk the walk. Or else you''ll watch yourself getting faced on our exclusive Slam Cam... These guys don''t even know how to spell "foul." Mastered one on one? There are six more game variations out there, chump. When you go to the hoop, the Slam Cam zooms in on the action. Reasons to lay down the cash: -"The Slam Cam"--get up-close-and-impersonal as players drive the lane -Over 700 frames of digitized animation -Five graffiti covered basketball courts -Side bets, ''cause only money really talks -Enough digitized trash talk to dis the entire neighborhood -Seven different streetball games: Sweat, 1-on-1, 2 Hot, Poison, Slams Only, in-2-it and Frenzy' FROM games WHERE igdb_id = 39018 ON CONFLICT (game_id, language_code) DO NOTHING;
