INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tekken', 'Tekken is a fighting game and the first entry in what would become the Tekken series and franchise. It was one of the earliest 3D animated fighting games applying many of the concepts found in Virtua Fighter by Sega. Contrary to traditional fighting games that involve inputting commands as rapidly and accurately as possible, Tekken slows the action down by emphasizing rhythm, strategy and deception over speed.' FROM games WHERE igdb_id = 1242 ON CONFLICT (game_id, language_code) DO NOTHING;
