INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xargon', 'The basic goal of Xargon is to advance through the map by completing levels. To finish a level, the player must find and reach the exit, which is found by traversing throughout the level. Xargon is unique in the sense that the player can purchase items at any point during the game. Emeralds are randomly placed in most levels. Purchasable items include health units, invincibility, and weapon upgrades.' FROM games WHERE igdb_id = 70129 ON CONFLICT (game_id, language_code) DO NOTHING;
