INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Feud', 'Family Feud Deluxe Edition for the 3DO system brings you over 4,000 new survey questions taken right from the hit television show. Play alone or with up to nine friends. Full motion video families battle against each other in the fully rendered Family Feud studio. After the host''s digitized voice reads the answer, ring in to guess the top survey responses from people across the country.' FROM games WHERE igdb_id = 175630 ON CONFLICT (game_id, language_code) DO NOTHING;
