INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stargate', 'Based on the movie of the same name, a mystical circular portal called a "Stargate" has been uncovered and Egyptologist and linguist Daniel Jackson is tasked with solving it. In the game you attempt to solve Stargate hyroglph combinations in a "Welltris"-puzzle-like manner, either in Hi-Score Skill Mode or 1 player or 2 player Battle Mode. It''s one of two games published by Acclaim Entertainment between 1994 and 1995 with the same cover art. This is the puzzle game from 1994 , the other is a action shooter platformer from 1995.' FROM games WHERE igdb_id = 19689 ON CONFLICT (game_id, language_code) DO NOTHING;
