INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kasumi Ninja', 'All hell is about to break loose! Stop the Evil Ninja Lord Gyaku from opening the Dragon Cloud temple''s portal to Hell and unleashing his demon minions upon Kasumi Island and the world. Battle it out in this bloody brawler in 1 Player Story mode or Two Player versus mode as one of the 8 all-time greatest warrior-fighters. Gain fighting skill and master special moves from bout to bout as you journey through the Underground Labyrinth to the Dragon Cloud temple where you''ll face your ultimate opponent: The Evil Ninja Lord Gyaku himself!' FROM games WHERE igdb_id = 40798 ON CONFLICT (game_id, language_code) DO NOTHING;
