INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'System Shock', 'A seminal cyberpunk first-person exploratory adventure game with RPG elements in which, waking up in the Citadel Space Station, a lone hacker has to survive corrupted enemies and collect audio logs and equipment from former station workers in order to shut down SHODAN, the station''s artificial intelligence that has killed everyone on board and now intends to destroy the world.' FROM games WHERE igdb_id = 23 ON CONFLICT (game_id, language_code) DO NOTHING;
