INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ishar-3-the-seven-gates-of-infinity', 2516, '1994-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co215s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2x4x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ishar 3: The Seven Gates of Infinity', 'So many battles... so much slaughter... and still there is no peace! The shadow of Chaos once more darkens the spires of the Citadel, for the evil spirit of Shandar seeks reincarnation in the vast body of the lord of Sith — last and most powerful of the ancient Black Dragons. Ishar 3: The Seven Gates of Infinity offers a role-playing adventure that surpasses its enormously popular predecessors; more than 100 characters with unique and life-like personalities (including animal companions). Ishar 3 also includes richly satisfying magic and combat systems with lush, spectacular night-and-day graphics, a challenging new time-travel feature. auto-mapping. extensive use of full-motion animated sequences. unlimited save-game facility and much, much more. The gates of Time are opening. Do you have the courage to pass through their mysterious portals?' FROM games WHERE igdb_id = 2516 ON CONFLICT (game_id, language_code) DO NOTHING;
