INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crusader-of-centy', 4552, '1994-06-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2899.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9dwp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crusader of Centy', 'Millions of years ago, heinous creatures that lurked in the shadows and darkness that blanketed the planet inhabited the Earth. When light finally broke through, only a few beasts were able to survive by burrowing into deep caverns. Over time, they multiplied, evolved, and patiently waited for the right time to emerge and rule the Earth once again. You are Corona, and you''ve just celebrated your 14th birthday. By law of the king, you must now go seek out these creatures of the dark and destroy them. As you travel in search of your destiny, you''ll make animal allies that will prove invaluable on your quest. Each level will offer mind-bending puzzles and challenges that will help you get one step closer to completing your mission.' FROM games WHERE igdb_id = 4552 ON CONFLICT (game_id, language_code) DO NOTHING;
