INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu! Beach Volley Da yo: Kunio-kun', 'One day, Kunio had been the practice dodgeball, Satomi Momozono, the passionate cheerleader at Nekketsu High, spots Kunio and informs him of the upcoming Nekketsu Volley Ball Club tournament. Again blinded by his desire to win the prize, Kunio drags his pal Riki along to compete in the volley ball tournament.' FROM games WHERE igdb_id = 49107 ON CONFLICT (game_id, language_code) DO NOTHING;
