INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ecstatica', 'Help to free Ecstatica in this terrifing graphic adventure with a fully explorable 3D environment, stunning animation, and ground breaking ellipsoid technology graphics. So lock your doors and check under your bed. Ecstatica is a nightmare like none you''ve experienced before.' FROM games WHERE igdb_id = 12423 ON CONFLICT (game_id, language_code) DO NOTHING;
