INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mary-shelley-s-frankenstein', 5403, '1994-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wc3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scszvn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mary Shelley''s Frankenstein', 'Based of the 1994 movie remake of Frankenstein, the player is the artificial man created by Victor Frankenstein. After Victor rejects his creation due to its hideous appearance, the creation flees from Victor and swears revenge on him. The player goes through a number of levels, battling anything that attacks with a wooden stick. It''s possible to set the tip of the stick on fire, by swinging it at the fire torches located on the walls. The player can also use a special attack: a blue ball coming out of the hands of the creation, which takes some of the player''s life away. There are also some simple puzzles to be solved in order to get through the levels.' FROM games WHERE igdb_id = 5403 ON CONFLICT (game_id, language_code) DO NOTHING;
