INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-need-for-speed', 90, '1994-08-31', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oiv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/h0klnhha0wv5ymkwmarw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Need for Speed', 'Welcome to The Need For Speed racing game. Here you''ll find spine-tingling action coupled with awesome graphics. As you race down an alpine road in your choice of eight high performance cars, you''ll be amazed by the detail and realism. The sophisticated physics model recreates the feel of the cars themselves; you''ll notice the difference in handling, breaking and just plain power. Plan your strategy for each track, there are six to choose from during regular play, and each demands a different style of driving. There''s also a bonus track if you win the Tournament. There are four game modes to try, with an option to compete against another driver over a modem. With different cars, different tracks, and different styles of racing fueling your need for speed, you''ll find your addiction growing to a fewer pitch. No need to worry, when you crash and burn in the game, there''s always another day.' FROM games WHERE igdb_id = 90 ON CONFLICT (game_id, language_code) DO NOTHING;
