INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('darius-gaiden', 6788, '1994-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eyg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar83b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darius Gaiden', 'Darius Gaiden is a two-dimensional shoot''em up. The player controls a space ship named the Silver Hawk and must guide it through scrolling stages, destroying enemies and avoiding obstacles along the way. The ship is armed with forward-firing missiles, aerial bombs and a protective force-field, all of which can be upgraded by various power-ups that are dropped by specially-colored enemies when they are destroyed by the player. New to the Silver Hawk''s arsenal in Darius Gaiden is the ''black hole bomb.'' When fired, the black hole bomb will create a large vortex in the center of the screen, which sucks in enemies and projectiles on the screen for a short moment, until it explodes into a powerful ball of lightning that inflicts massive damage onto every enemy on the screen. Another feature introduced Darius Gaiden is the ability to capture minibosses, who appear in every stage. Each miniboss has a small, circular ball placed on them that, after receiving enough damage, will detach and float away, causing the miniboss to turn idle. If the player collects the ball, the miniboss will follow and aid the player. After a brief period of time, or the player loses a life, the miniboss will explode. A few months following release, update to the arcade version was later released entitled "Darius Gaiden Extra Edition". This version of arcade game contains rearranged levels, as well as automatically-enabled auto fire, two extra weapon power levels (bigger wave shot and a bigger red wave shot as well) and an all-stage mode which can be accessed by starting the game in 2P side.' FROM games WHERE igdb_id = 6788 ON CONFLICT (game_id, language_code) DO NOTHING;
